"""Mutants for the backend-foundation migrations (20261010*). Each one breaks a single protection; the suite must then FAIL.
Keys: 'foundation', 'profile', 'world', 'social', 'vehjobs', 'econ' (see NAMES in mutation.py)."""


def make(sub, resub):
    G = lambda fn, sig: (lambda t: t + f"\ngrant execute on function {fn}({sig}) to authenticated;\n")
    A = lambda fn, sig: (lambda t: t + f"\ngrant execute on function {fn}({sig}) to anon;\n")
    T = lambda s: (lambda t: t + "\n" + s + "\n")
    M = {}
    # ------------------------------------------------------------------ foundation: rate limit, notifications, analytics
    M["rate limit: never rejects"] = ("foundation", lambda t: sub(t, "if v_hits > p_max then raise exception 'rate_limited'; end if;", ""))
    M["notifications: mark_read ownership removed"] = ("foundation", lambda t: sub(t, "where id = p_id and player_id = auth.uid();\n  if not found then raise exception 'notification_not_found'", "where id = p_id;\n  if not found then raise exception 'notification_not_found'"))
    M["notifications: list shows every player's inbox"] = ("foundation", lambda t: sub(t, "where player_id = v_uid and (p_before is null or created_at < p_before)", "where (p_before is null or created_at < p_before)"))
    M["notifications: dedupe key ignored"] = ("foundation", lambda t: sub(t, "coalesce(p_meta, '{}'::jsonb), p_dedupe)", "coalesce(p_meta, '{}'::jsonb), null)"))
    M["notifications: unread count spans all players"] = ("foundation", lambda t: sub(t, "return (select count(*)::int from notifications where player_id = auth.uid() and read_at is null);", "return (select count(*)::int from notifications where read_at is null);"))
    M["notifications: mark-all touches every player"] = ("foundation", lambda t: sub(t, "update notifications set read_at = now() where player_id = auth.uid() and read_at is null;", "update notifications set read_at = now() where read_at is null;"))
    M["notifications: inbox never pruned"] = ("foundation", lambda t: sub(t, "offset greatest(cfg('notifications_keep')::int, 20));", "offset 100000);"))
    M["analytics: client may report any event"] = ("foundation", lambda t: sub(t, "if p_name not in ('multiplayer_session_started','multiplayer_session_ended') then raise exception 'event_not_allowed'; end if;", ""))
    M["analytics: e-mail key survives sanitising"] = ("foundation", lambda t: sub(t, "where k in ('players','duration_s','region','reason')", "where k in ('players','duration_s','region','reason','email')"))
    M["grants: track_event to anon"] = ("foundation", A("track_event", "text, jsonb"))
    M["grants: analytics_events readable by clients"] = ("foundation", T("grant select on analytics_events to authenticated;"))
    M["grants: notifications writable by clients"] = ("foundation", T("grant insert on notifications to authenticated;"))
    M["grants: _notify executable by clients"] = ("foundation", G("_notify", "uuid, text, text, text, jsonb, text"))
