    M["friends: find_player allows prefix search"] = ("social", lambda t: sub(t, "select id into v_id from profiles where username = lower(trim(p_username));", "select id into v_id from profiles where username like lower(trim(p_username)) || '%' order by username limit 1;"))
    M["friends: cannot-friend-self check removed"] = ("social", lambda t: sub(t, "if p_player = v_uid then raise exception 'cannot_friend_self'; end if;", ""))
