    M["convoy: kick by non-leader"] = ("social", lambda t: sub(t, "if not found then raise exception 'not_leader'; end if;\n  if p_player = v_uid then raise exception 'cannot_kick_leader'; end if;", "if p_player = v_uid then raise exception 'cannot_kick_leader'; end if;"))
    M["convoy: invite answered by anyone"] = ("social", lambda t: sub(t, "where id = p_invite and invitee_id = v_uid and status = 'pending' for update;", "where id = p_invite and status = 'pending' for update;"))
    M["convoy: expired invite accepted"] = ("social", lambda t: sub(t, "if i.expires_at <= now() then raise exception 'invite_expired'; end if;", ""))
    M["convoy: options changed by non-leader"] = ("social", lambda t: sub(t, "where leader_id = v_uid and disbanded_at is null for update;\n  if not found then raise exception 'not_leader'; end if;\n  select count(*) into v_n", "where disbanded_at is null limit 1 for update;\n  if not found then raise exception 'not_leader'; end if;\n  select count(*) into v_n"))
    M["convoy: leadership handed to a non-member"] = ("social", lambda t: sub(t, "if p_player = v_uid or not exists (select 1 from convoy_members where convoy_id = c.id and player_id = p_player) then raise exception 'not_a_member'; end if;", "if p_player = v_uid then raise exception 'not_a_member'; end if;"))
    M["convoy: inviting a player already in a convoy"] = ("social", lambda t: sub(t, "if exists (select 1 from convoy_members where player_id = p_player) then raise exception 'player_in_convoy'; end if;", ""))
