    M["leaderboard friends: distance and jobs swapped"] = ("lbsocial", lambda t: sub(t, "when 'distance' then pr.distance_km when 'jobs' then pr.jobs_completed else pr.lifetime_earnings end)::numeric from profiles pr where pr.id = i.id)", "when 'distance' then pr.jobs_completed when 'jobs' then pr.distance_km else pr.lifetime_earnings end)::numeric from profiles pr where pr.id = i.id)"))
    M["leaderboard friends: weekly xp accepted"] = ("lbsocial", lambda t: sub(t, "if p_period = 'weekly' and p_metric = 'xp' then raise exception 'unsupported_period'; end if;\n\n  create temp table if not exists _flb", "create temp table if not exists _flb"))
    M["leaderboard friends: the board is not ranked"] = ("lbsocial", lambda t: sub(t, "'avatar_id', pr.avatar_id, 'level', pr.level, 'country_code', pr.country_code, 'value', x.value) order by x.rank, x.player_id), '[]'::jsonb) into v_items\n    from (select player_id, value, rank() over (order by value desc) as rank from _flb) x", "'avatar_id', pr.avatar_id, 'level', pr.level, 'country_code', pr.country_code, 'value', x.value) order by x.player_id), '[]'::jsonb) into v_items\n    from (select player_id, value, 1 as rank from _flb) x"))
    M["leaderboard search: rank is not the global rank"] = ("lbsocial", lambda t: sub(t, "(select count(*) + 1 from profiles o where o.%1$I > p.%1$I) as rank\n                from profiles p where p.%1$I > 0 and (strpos", "1 as rank\n                from profiles p where p.%1$I > 0 and (strpos"))
